    for b in [-2,-1,-0.5,0,0.5,1,1.5,2,3]:
        cands[f'A^{a} t^{b}']=A**a*t**b
for a in [0,1,2]:
    for c in [0.1,0.3,0.5,1,2]:
        cands[f'A^{a} exp(-{c}t)']=A**a*np.exp(-c*t)
        cands[f'A^{a} exp(-{c}A)']=A**a*np.exp(-c*A)
        cands[f'A^{a} /(1+{c}A)']=A**a/(1+c*A)
names=list(cands); M=np.column_stack([cands[k] for k in names])
sel=[]
for step in range(6):
    best=None
    for j in range(len(names)):
        if j in sel: continue
        X=M[:,sel+[j]]
